const setAutoLineClassification = `-- name: SetAutoLineClassification :execrows
UPDATE statement_transactions
SET account_code = $1, classification_origin = $2, classification_pending = $3,
    classification_rule_id = $4, classification_history_id = $5,
    classification_suggestion_id = NULL, classified_by = NULL, classified_at = $6
WHERE id = $7 AND company_id = $8
  AND (classification_origin IS NULL OR classification_pending)
`

type SetAutoLineClassificationParams struct {
	AccountCode  *string
	Origin       *string
	Pending      bool
	RuleID       *string
	HistoryID    *string
	ClassifiedAt *time.Time
	ID           string
	CompanyID    string
}

// A classificação automática (regra, histórico ou à espera do agente): só na linha ainda sem
// classificação confirmada, então nunca troca a do contador, mesmo em corrida.
func (q *Queries) SetAutoLineClassification(ctx context.Context, arg SetAutoLineClassificationParams) (int64, error) {
	result, err := q.db.Exec(ctx, setAutoLineClassification,
		arg.AccountCode,
		arg.Origin,
		arg.Pending,
		arg.RuleID,
		arg.HistoryID,
		arg.ClassifiedAt,
		arg.ID,
		arg.CompanyID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setLineClassification = `-- name: SetLineClassification :exec
UPDATE statement_transactions
SET account_code = $1, classification_origin = $2, classification_pending = $3,
    classification_rule_id = $4, classification_history_id = $5,
    classification_suggestion_id = $6, classified_by = $7,
    classified_at = $8
WHERE id = $9 AND company_id = $10
`

type SetLineClassificationParams struct {
	AccountCode  *string
	Origin       *string
	Pending      bool
	RuleID       *string
	HistoryID    *string
	SuggestionID *string
	ClassifiedBy *string
	ClassifiedAt *time.Time
	ID           string
	CompanyID    string
}

// A classificação humana (correção ou sugestão aceita) e o que a produziu (o CHECK da 0029
// confere a coerência).
func (q *Queries) SetLineClassification(ctx context.Context, arg SetLineClassificationParams) error {
	_, err := q.db.Exec(ctx, setLineClassification,
		arg.AccountCode,
		arg.Origin,
		arg.Pending,
		arg.RuleID,
		arg.HistoryID,
		arg.SuggestionID,
		arg.ClassifiedBy,
		arg.ClassifiedAt,
		arg.ID,
		arg.CompanyID,
	)
	return err
}

const updateChartAccount = `-- name: UpdateChartAccount :one
UPDATE chart_accounts SET name = $1, active = $2, updated_at = $3
WHERE id = $4 AND company_id = $5
RETURNING id, company_id, code, name, active, created_at, updated_at
`

type UpdateChartAccountParams struct {
	Name      string
	Active    bool
	Now       time.Time
	ID        string
	CompanyID string
}

func (q *Queries) UpdateChartAccount(ctx context.Context, arg UpdateChartAccountParams) (ChartAccount, error) {
	row := q.db.QueryRow(ctx, updateChartAccount,
		arg.Name,
		arg.Active,
		arg.Now,
		arg.ID,
		arg.CompanyID,
	)
	var i ChartAccount
	err := row.Scan(
		&i.ID,
		&i.CompanyID,
		&i.Code,
		&i.Name,
		&i.Active,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertChartAccount = `-- name: UpsertChartAccount :one
INSERT INTO chart_accounts (company_id, code, name, created_at, updated_at)
VALUES ($1, $2, $3, $4, $4)
ON CONFLICT (company_id, code) DO UPDATE SET name = EXCLUDED.name, active = true, updated_at = EXCLUDED.updated_at
RETURNING (xmax = 0) AS inserted
`

type UpsertChartAccountParams struct {
	CompanyID string
	Code      string
	Name      string
	Now       time.Time
}

// Importação do plano: conta nova entra; a que já existe ganha o nome do arquivo e volta a ativa.
func (q *Queries) UpsertChartAccount(ctx context.Context, arg UpsertChartAccountParams) (bool, error) {
	row := q.db.QueryRow(ctx, upsertChartAccount,
		arg.CompanyID,
		arg.Code,
		arg.Name,
		arg.Now,
	)
	var inserted bool
	err := row.Scan(&inserted)
	return inserted, err
}
